view: leads_only_approved_by_lending_club {
  derived_table: {
    sql: select distinct lead_uuid
         from (select lead_uuid,
                      sum(case
                                when (last_demand_api_response_type = 'approval' and {% condition demand_partner_sub_account_name %} demand_sub_account_name {% endcondition %}) then 1
                                else 0
                          end) as approved_by_lender,
                      sum(case
                                when (last_demand_api_response_type = 'approval' and not ({% condition demand_partner_sub_account_name %} demand_sub_account_name {% endcondition %})) then 1
                                else 0
                          end) as rejected_by_lender
               from public.lead_by_demand
               group by lead_uuid
               order by approved_by_lender)
         where approved_by_lender > 0
          and rejected_by_lender = 0 ;;
  }

  filter: demand_partner_sub_account_name {
    type: string
  }

  measure: count {
    type: count_distinct
    sql: ${lead_uuid} ;;
    drill_fields: [detail*]
  }

  dimension: lead_uuid {
    type: string
    primary_key: yes
    sql: ${TABLE}.lead_uuid ;;
  }

  set: detail {
    fields: [lead_uuid]
  }

